function editDepartment(id){const item=cfg.departments.find(d=>d.id===id)||{id:uid(),name:'',enabled:true};form(id?'编辑部门':'新建部门','<div class="ec-form-grid">'+field('name','部门名称 *',item.name,'text',true)+field('code','部门编码 *',item.code,'text',true)+field('leader','负责人',item.leader)+field('phone','负责人电话',item.phone)+field('description','部门职责',item.description)+'</div><p class="ec-help">此处维护组织节点；职工调动请通过“调整组织”更新花名册。</p>',async body=>{if(cfg.departments.some(d=>d.id!==item.id&&(d.name===body.name||d.code===body.code)))throw Error('部门名称或编码重复');await update(()=>{const index=cfg.departments.findIndex(d=>d.id===item.id),next={...item,...body};if(index<0)cfg.departments.push(next);else cfg.departments[index]=next;});});}
function editPosition(id){const item=cfg.positions.find(p=>p.id===id)||{id:uid(),name:'',enabled:true};form(id?'编辑岗位':'新增岗位','<div class="ec-form-grid">'+field('name','岗位名称 *',item.name,'text',true)+field('code','岗位编码 *',item.code,'text',true)+field('exposure','职业危害因素（用顿号分隔）',item.exposure)+field('description','岗位职责 / 防护说明',item.description)+'</div>',async body=>{if(cfg.positions.some(p=>p.id!==item.id&&(p.name===body.name||p.code===body.code)))throw Error('岗位名称或编码重复');await update(()=>{const index=cfg.positions.findIndex(p=>p.id===item.id),next={...item,...body};if(index<0)cfg.positions.push(next);else cfg.positions[index]=next;});});}
function movePeople(){if(!selected.size)throw Error('请先选择需要调整的职工');if(selected.size>100)throw Error('每次最多调整100位职工');const orgs=Object.fromEntries(cfg.departments.filter(d=>d.enabled!==false).map(d=>[d.name,d.name]));form('调整职工组织','<p class="ec-help">即将调整 '+selected.size+' 位职工的所属组织。岗位和班组留空时保留原值。</p><div class="ec-form-grid">'+select('org','目标单位 *',orgs)+field('team','目标班组')+select('job','目标岗位',{'':'保留原岗位',...Object.fromEntries(cfg.positions.filter(p=>p.enabled!==false).map(p=>[p.name,p.name]))})+'</div>',async body=>{if(!body.org)throw Error('请选择目标组织');let done=0;const failed=[];for(const id of selected){const p=person(id);if(!p)continue;try{const next={...p,org:body.org,team:body.team||p.team,job:body.job||p.job,legacyUserCode:p.legacyUserCode||''};if(realPeople){const saved=await api('records/'+id,'PUT',next);Object.assign(p,saved);}else Object.assign(p,next);done++;}catch(error){failed.push(p.code+'：'+error.message);}}if(failed.length)throw Error('已调整 '+done+' 人；'+failed.join('；'));selected.clear();});}
function render(){charts.forEach(c=>c.dispose());charts=[];const app=$('app');app.removeAttribute('aria-busy');if(pageType==='list')listPage();else if(['groups','tags'].includes(pageType))groupTagPage();else if(pageType==='bindings')bindingsPage();else if(pageType==='import')importPage();else organizationPage();wire();}
function wire(){const form=$('ec-filters');if(form)form.onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));if(values.min&&values.max&&Number(values.min)>Number(values.max)){toast('关联人数上限不能小于下限');return;}filters=values;currentPage=1;render();};const size=$('ec-limit');if(size)size.onchange=()=>{limit=Number(size.value);currentPage=1;render();};const all=$('select-all');if(all){all.checked=currentRows.length>0&&currentRows.every(p=>selected.has(p.id));all.onchange=()=>{currentRows.forEach(p=>all.checked?selected.add(p.id):selected.delete(p.id));render();};}document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select);$('selected-count').textContent=selected.size;});document.querySelectorAll('[data-map]').forEach(el=>el.onchange=()=>{importData.mapping[Number(el.dataset.map)]=el.value;importData.stage=3;render();});}
