document.addEventListener('click',event=>{const button=event.target.closest('[data-act]');if(button){event.preventDefault();Promise.resolve(action(button.dataset.act,button.dataset.id)).catch(error=>toast(error.message));return;}const p=event.target.closest('[data-pager]');if(p){currentPage=Number(p.dataset.pager);render();}const t=event.target.closest('[data-tab]');if(t){tab=t.dataset.tab;currentPage=1;render();}const org=event.target.closest('[data-org]');if(org){selectedOrg=org.dataset.org;filters={};currentPage=1;selected.clear();render();}const sectionButton=event.target.closest('[data-section]');if(sectionButton){section=sectionButton.dataset.section;filters={};currentPage=1;render();}});
function fallbackPeople(){const names=['张新','李红','王强','刘娜','赵军','孙浩','陈建','周婷','郭亮','黄伟','吴峰','郑海','冯磊','陈亮','刘刚','徐强'];return Array.from({length:36},(_,i)=>({id:'display-person-'+i,name:names[i%names.length],code:'GZ'+(100238+i),sex:i%4===1?'女':'男',age:33+i%18,birth:(1990-i%18)+'-03-02',phone:'1380000'+String(5600+i),org:['综采一队','掘进二队','机电运输部','通风安全部'][i%4],team:['综采一班','掘进一班','机电班','通风班'][i%4],job:['采煤工','掘进工','机电维修工','安全员'][i%4],exposure:['粉尘、噪声','粉尘、噪声、高温','噪声、振动','噪声'][i%4],risk:['low','medium','high','unknown'][i%4],status:['archived','archived','pending','draft'][i%4],bound:i%3!==0,rowVersion:1}));}
