$('page-title').textContent=titles[pageType][0];$('page-subtitle').textContent=titles[pageType][1];$('app').innerHTML='<div class="ec-loading">正在整理职工信息…</div>';$('fullscreen').onclick=()=>{const p=document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();p.catch(()=>toast('浏览器未允许全屏'));};document.addEventListener('click',event=>{if(event.target.closest('[data-act=reload]'))load();});window.addEventListener('resize',()=>charts.forEach(c=>c.resize()));tick();const timer=setInterval(tick,1000);window.addEventListener('pagehide',()=>{clearInterval(timer);clearTimeout(toastTimer);charts.forEach(c=>c.dispose());},{once:true});load();
